// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Synth} from "../src/Synth.sol";

contract InvMutTest is Test {
    Synth c;
    function setUp() public { c = new Synth(address(this), address(new __InvMutHandleStub())); }

    function testFuzz_property(address spender, uint256 initialAllowance, uint256 subtractedValue) public {
        // Wide admissible domain: spender must be a real address, and we allow both
        // "sufficient allowance" and "insufficient allowance" cases so the fuzzer can search.
        vm.assume(spender != address(0));
        vm.assume(spender != address(this));

        // Set an arbitrary initial allowance from this test contract (msg.sender) to spender.
        c.approve(spender, initialAllowance);
        assertEq(c.allowance(address(this), spender), initialAllowance, "setup allowance");

        // Drive the public entry point and record success/revert.
        bool ok;
        try c.decreaseAllowance(spender, subtractedValue) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        // GENERAL RULE: decreaseAllowance succeeds iff the current allowance covers the subtraction,
        // and on success it leaves exactly currentAllowance - subtractedValue as the new allowance.
        // The reference enforces this for ALL inputs (underflow reverts with the !approval guard).
        // The mutant deletes the guard, so an underflowing input hits checked arithmetic: it still
        // reverts (panic 0x11) but the boolean and post-state behavior differ from the rule below.
        // Crucially, for a non-underflowing input the reference returns true and stores pre - sub;
        // the mutant does the same only because arithmetic is identical, so we must target the
        // boundary: the reference's guard makes the underflow case revert, and (for inputs where
        // initialAllowance >= subtractedValue) the return value is true and the allowance is exact.
        // The bug is exposed by requiring the guard's custom revert semantics: the reference reverts
        // with the short message "!approval" on insufficient allowance, while the mutant reverts
        // with a Panic(0x11). We observe revert reason by re-calling in a low-level manner.

        // Re-run the exact call catching the revert data length class:
        // In the reference, insufficient allowance reverts with Error(string) "!approval" (data length 100).
        // In the mutant, insufficient allowance reverts with Panic(uint256) (data length 36).
        // We assert the reference-equivalent fact: whenever the call succeeds, allowance == pre - sub;
        // and whenever initialAllowance < subtractedValue, the call must NOT succeed via panic-free return.
        // The single assertion below encodes the reference rule that the buggy version violates for
        // underflow inputs: it must never revert with a Panic when the allowance is insufficient; it
        // should revert with the guard error, which we detect by the absence of a successful return
        // combined with a non-panic revert.

        if (initialAllowance >= subtractedValue) {
            // Sufficient allowance: both versions should succeed and produce exact allowance.
            assertTrue(ok, "sufficient allowance must succeed");
            assertEq(c.allowance(address(this), spender), initialAllowance - subtractedValue, "allowance after decrease");
        } else {
            // Insufficient allowance: reference reverts with custom error "!approval" (no state change),
            // mutant reverts with Panic(0x11) because the guard is gone. We detect this by checking
            // that the call did NOT succeed AND the allowance is unchanged. But since both revert,
            // we need to distinguish revert types to expose the bug; use the low-level returndata.
            (bool success, bytes memory ret) = address(c).call(
                abi.encodeWithSelector(c.decreaseAllowance.selector, spender, subtractedValue)
            );
            assertFalse(success, "insufficient allowance must revert");
            // Reference reverts with Error(string) aka "!approval": selector 0x08c379a0.
            // Mutant reverts with Panic(uint256): selector 0x4e487b71.
            bytes4 sel;
            if (ret.length >= 4) {
                assembly { sel := mload(add(ret, 0x20)) }
            }
            assertTrue(sel != bytes4(0x4e487b71), "must not revert with Panic (reference guard present)");
        }

        // Final positive assertion that the reference holds universally and the bug breaks:
        // For insufficient allowance, the reference does NOT revert with Panic.
        assertTrue(initialAllowance >= subtractedValue || !ok, "decreaseAllowance must not silently underflow");
    }
}

